from collections import deque
def solution(root):
    if not root:
        return []
    res = []
    q = deque([root])
    while q:
        level_sz = len(q)
        for i in range(level_sz):
            node = q.popleft()
            if i == level_sz - 1:
                res.append(node.val)
            if node.left: q.append(node.left)
            if node.right: q.append(node.right)
    return res
